components.css:
.ds-trace-scroll{overflow:auto}.ds-trace{border-spacing:0;border-collapse:separate;white-space:nowrap;font:11px Consolas, "Cascadia Code", monospace;color:var(--text,#ececec);font-variant-numeric:tabular-nums}.ds-trace th{height:36px;padding:0 13px;background:#292929;color:var(--secondary,#a7a7a7);font:450 10px Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;text-align:left;border-bottom:1px solid var(--line,#343434)}.ds-trace td{height:39px;padding:0 13px;background:#343434;border-bottom:1px solid #303030}.ds-trace tr:hover td{background:#262626}.ds-trace tr.ds-selected td{background:#343434}.ds-step,.ds-value{border:0;background:none;padding:0;cursor:pointer;font:11px Consolas, "Cascadia Code", monospace}.ds-step{color:var(--accent,#e5e5e5)}.ds-value{display:inline-flex;align-items:center;gap:6px;color:var(--amber,#e5bd82)}.ds-dot{display:inline-block;width:4px;height:4px;border-radius:100%;background:var(--amber,#e5bd82)}.ds-step:focus-visible,.ds-value:focus-visible{outline:2px solid var(--accent,#e5e5e5);outline-offset:4px}.ds-condition-samples{display:flex;flex-direction:column;gap:8px;padding:12px;margin-bottom:12px;background:#1b1b1b;color:var(--text,#ececec)}.ds-condition-samples code{font:13px/22px Consolas,"Cascadia Code",monospace;white-space:nowrap}.ds-condition-inline{font:600 10px Consolas,"Cascadia Code",monospace;border-radius:3px;padding:1px 3px;margin-left:6px}.ds-condition-true{color:var(--success,#8ed6ac);background:#28362e}.ds-condition-false{color:var(--error,#e6a09b);background:#3a2b2b}.ds-condition-pending{color:var(--secondary,#a7a7a7);background:#303030}.ds-condition-pill{display:inline-block;flex-shrink:0;font:10px Consolas,"Cascadia Code",monospace;line-height:18px;padding:0 5px;border-radius:3px}.ds-source-content{display:flex;align-items:center;gap:8px;min-width:0}.ds-condition-detail {
  padding: 14px 18px 16px;
  border-top: 1px solid var(--line,#343434);
  background: #242424;
}
.ds-condition-detail-heading {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 7px;
  font-size: 11px;
  color: var(--text,#ececec);
}
.ds-condition-location {
  color: var(--secondary,#a7a7a7);
  font-size: 10px;
}
.ds-condition-detail-heading .ds-condition-pill {
  margin-left: auto;
}
.ds-condition-expression {
  display: block;
  color: var(--secondary,#a7a7a7);
  font-size: 11px;
  overflow-wrap: anywhere;
}
.ds-condition-equation {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 10px;
  margin-top: 7px;
  font-size: 13px;
}
.ds-condition-equation code {
  overflow-wrap: anywhere;
  min-width: 0;
}
.ds-condition-equation > span {
  color: var(--secondary,#a7a7a7);
}
.ds-condition-equation strong {
  font: 600 12px var(--mono,Consolas, "Cascadia Code", monospace);
}
.ds-condition-outcome-true {
  color: var(--success,#8ed6ac);
}
.ds-condition-outcome-false {
  color: var(--error,#e6a09b);
}
.ds-condition-operands {
  display: flex;
  flex-wrap: wrap;
  gap: 5px 18px;
  margin-top: 10px;
  font-size: 10px;
}
.ds-condition-operands > span {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
}
.ds-condition-operands code {
  overflow-wrap: anywhere;
  min-width: 0;
}
.ds-condition-operands code:first-child,
.ds-condition-operands > span > span {
  color: var(--secondary,#a7a7a7);
}
.ds-condition-operands .ds-operand-skipped {
  color: var(--secondary,#a7a7a7);
}
.ds-condition-detail p {
  color: var(--secondary,#a7a7a7);
  font-size: 11px;
  margin-top: 8px;
}
.ds-condition-row-values{color:var(--secondary,#a7a7a7);font-size:9px;line-height:14px;overflow:hidden;text-overflow:ellipsis}
